        where: { id: bill.id },
        data: { status: "paid", paid_at: new Date() },
      });
      const online = await tx.payments.create({
        data: {
          org_id: f.orgId,
          lease_id: f.leaseId,
          amount_sen: 50000n,
          method: "online",
          status: "approved",
          received_at: new Date(),
          gateway_bill_id: bill.id,
        },
      });
      await allocatePayment(tx, online.id);
    });
    expect(await statusOf(approvePayment(f.managerActor, pending.id))).toBe(422);
    const after = await prisma.payments.findUniqueOrThrow({ where: { id: pending.id } });
    expect(after.status).toBe("pending_verification");
    expect(await allocatedTo(pending.id)).toBe(0n);
  });

  test("reject needs a reason and a pending payment", async () => {
    const f = await createFixture();
    const payment = await recordPayment(f.staffActor, f.leaseId, cash(1000));
    expect(
      await statusOf(rejectPayment(f.managerActor, payment.id, { reason: "  abc  " })),
    ).toBe(400);
    expect(
      await rejectPayment(f.managerActor, payment.id, { reason: "Slip unreadable" }),
    ).toEqual({ status: "rejected" });
    expect(
      await statusOf(rejectPayment(f.managerActor, payment.id, { reason: "Again please" })),
    ).toBe(409);
    expect(await statusOf(approvePayment(f.managerActor, payment.id))).toBe(409);
  });

  test("void removes only that payment's allocations", async () => {
    const f = await createFixture();
    const first = await recordPayment(f.managerActor, f.leaseId, cash(100000));
    const second = await recordPayment(f.managerActor, f.leaseId, cash(50000));
    const secondBefore = await prisma.payment_allocations.findMany({
      where: { payment_id: second.id },
      orderBy: { invoice_id: "asc" },
    });
    expect(await statusOf(voidPayment(f.managerActor, first.id, { reason: "no" }))).toBe(400);
    expect(
      await voidPayment(f.managerActor, first.id, { reason: "Cheque bounced" }),
    ).toEqual({ status: "voided" });
    expect(await allocatedTo(first.id)).toBe(0n);
    const secondAfter = await prisma.payment_allocations.findMany({
      where: { payment_id: second.id },
      orderBy: { invoice_id: "asc" },
    });
    expect(secondAfter).toEqual(secondBefore);
    expect(
      await statusOf(voidPayment(f.managerActor, first.id, { reason: "Cheque bounced" })),
    ).toBe(409);
    // Payments are never deleted.
    expect(await prisma.payments.count({ where: { lease_id: f.leaseId } })).toBe(2);
  });

  test("allocation order: due date, then deposit before rent, then period", async () => {
    const f = await createFixture({
      lease: {
        startDate: "2026-01-31",
        endDate: "2026-07-15",
        monthlyRentSen: 150000,
        depositSen: 300000,
      },
    });
    await recordPayment(f.managerActor, f.leaseId, cash(350000));
    const detail = await getLeaseDetail(f.managerActor, f.leaseId);
    expect(detail.invoices.map((i) => [i.kind, i.periodIndex, i.paidSen])).toEqual([
      ["deposit", null, 300000],
      ["rent", 0, 50000],
      ["rent", 1, 0],
      ["rent", 2, 0],
      ["rent", 3, 0],
      ["rent", 4, 0],
      ["rent", 5, 0],
    ]);
    expect(detail.invoices[1]?.status).toBe("overdue");
    expect(detail.invoices[0]?.status).toBe("paid");
    expect(detail.payments[0]?.receivedAt).toBe("2026-01-15T10:00:00+08:00");
  });
});

describe("access", () => {
  test("another organization's manager gets 404; wrong role gets 403", async () => {
    const f = await createFixture();
    const other = await createFixture();
    const payment = await recordPayment(f.staffActor, f.leaseId, cash(1000));
    expect(await statusOf(getLeaseDetail(other.managerActor, f.leaseId))).toBe(404);
    expect(await statusOf(recordPayment(other.managerActor, f.leaseId, cash(1)))).toBe(404);
    expect(await statusOf(approvePayment(other.managerActor, payment.id))).toBe(404);
    expect(
      await statusOf(voidPayment(other.managerActor, payment.id, { reason: "whatever" })),
    ).toBe(404);
    expect(await statusOf(getLeaseDetail(other.tenantActor, f.leaseId))).toBe(404);
    expect(await statusOf(getLeaseDetail(f.managerActor, "not-a-uuid"))).toBe(404);
    // Visible, but the role may not: 403.
    expect(await statusOf(approvePayment(f.staffActor, payment.id))).toBe(403);
    expect(await statusOf(approvePayment(f.tenantActor, payment.id))).toBe(403);
    expect(await statusOf(recordPayment(f.tenantActor, f.leaseId, cash(1)))).toBe(403);
    expect(await statusOf(getLeaseDetail(f.tenantActor, f.leaseId))).toBe(200);
    expect(await statusOf(collectionsReport(f.tenantActor, "2026-01", "2026-02"))).toBe(403);
  });

  test("a manager cannot create a lease on another org's unit or tenant", async () => {
    const f = await createFixture();
    const other = await createFixture();
    const terms = { startDate: "2030-01-01", endDate: "2030-12-31", monthlyRentSen: 1000, depositSen: 0 };
    expect(
      await statusOf(
        createLease(f.managerActor, { ...terms, unitId: other.spareUnitId, tenantId: f.tenantId }),
      ),
    ).toBe(404);
    expect(
      await statusOf(
        createLease(f.managerActor, { ...terms, unitId: f.spareUnitId, tenantId: other.tenantId }),
      ),
    ).toBe(404);
    expect(
      await statusOf(
        createLease(f.staffActor, { ...terms, unitId: f.spareUnitId, tenantId: f.tenantId }),
      ),
    ).toBe(403);
  });
});

describe("leases", () => {
  test("creating a lease stores exactly generateSchedule's invoices", async () => {
    const terms = {
      startDate: "2026-01-31",
      endDate: "2026-07-15",
      monthlyRentSen: 150000,
      depositSen: 300000,
    };
    const f = await createFixture({ lease: terms });
    const invoices = await prisma.invoices.findMany({
      where: { lease_id: f.leaseId },
      orderBy: [{ due_date: "asc" }, { kind: "asc" }, { period_index: "asc" }],
    });
    expect(
      invoices.map((i) => ({
        kind: i.kind,
        periodIndex: i.period_index,
        periodStart: i.period_start && calendarDateFromDb(i.period_start),
        periodEnd: i.period_end && calendarDateFromDb(i.period_end),
        dueDate: calendarDateFromDb(i.due_date),
        amountSen: Number(i.amount_sen),
      })),
    ).toEqual(generateSchedule(terms));
    expect(
      await prisma.audit_log.count({ where: { entity_id: f.leaseId, action: "lease.created" } }),
    ).toBe(1);
  });

  test("overlapping leases are refused, including two at the same moment", async () => {
    const f = await createFixture(); // 2026-01-01..2026-03-31 on unitId
    const base = { tenantId: f.tenantId, monthlyRentSen: 1000, depositSen: 0 };
    expect(
      await statusOf(
        createLease(f.managerActor, {
          ...base,
          unitId: f.unitId,
          startDate: "2026-03-31", // inclusive end touches
          endDate: "2026-06-30",
        }),
      ),
    ).toBe(409);
    expect(
      await statusOf(
        createLease(f.managerActor, {
          ...base,
          unitId: f.unitId,
          startDate: "2026-04-01",
          endDate: "2026-06-30",
        }),
      ),
    ).toBe(200);
    expect(
      await statusOf(
        createLease(f.managerActor, {
          ...base,
          unitId: f.unitId,
          startDate: "2026-02-31",
          endDate: "2026-06-30",
        }),
      ),
    ).toBe(400);
    const concurrent = await Promise.all([
      statusOf(
        createLease(f.managerActor, {
          ...base,
          unitId: f.spareUnitId,
          startDate: "2027-01-01",
          endDate: "2027-12-31",
        }),
      ),
      statusOf(
        createLease(f.managerActor, {
          ...base,
          unitId: f.spareUnitId,
          startDate: "2027-06-01",
          endDate: "2028-05-31",
        }),
      ),
    ]);
    expect(concurrent.sort()).toEqual([200, 409]);
    expect(await prisma.leases.count({ where: { unit_id: f.spareUnitId } })).toBe(1);
  });
});

describe("collections report", () => {
  test("groups by Malaysia month, includes empty months, counts approved only", async () => {
    const f = await createFixture();
    await recordPayment(f.managerActor, f.leaseId, cash(30000, "2026-01-31T10:00:00+08:00"));
    // 2026-03-01 00:30 in Malaysia is still February in UTC.
    await recordPayment(f.managerActor, f.leaseId, cash(20000, "2026-02-28T16:30:00Z"));
    await recordPayment(f.staffActor, f.leaseId, cash(5000, "2026-02-10T10:00:00+08:00"));
    const voided = await recordPayment(f.managerActor, f.leaseId, cash(7000, "2026-02-11T10:00:00+08:00"));
    await voidPayment(f.managerActor, voided.id, { reason: "Recorded twice" });
    expect(await collectionsReport(f.staffActor, "2026-01", "2026-03")).toEqual([
      { month: "2026-01", collectedSen: 30000 },
      { month: "2026-02", collectedSen: 0 },
      { month: "2026-03", collectedSen: 20000 },
    ]);
    expect(await collectionsReport(f.staffActor, "2025-12", "2025-12")).toEqual([
      { month: "2025-12", collectedSen: 0 },
    ]);
  });

  test("invalid ranges are 400", async () => {
    const f = await createFixture();
    for (const [from, to] of [
      ["2026-13", "2026-12"],
      ["2026-1", "2026-02"],
      ["2026-03", "2026-01"],
      [null, "2026-01"],
      ["2000-01", "2026-01"],
    ]) {
      expect(await statusOf(collectionsReport(f.managerActor, from, to))).toBe(400);
    }
  });
});

